// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;

    function setUp() public { c = new W_WALLET(address(this)); }

    function testFuzz_property(address sender, uint256 amount, uint256 unlockTime) public {
        amount = bound(amount, 0, 1 ether * 1000);
        vm.assume(sender != address(0));

        RevertingLog badLog = new RevertingLog();
        W_WALLET c_bad = new W_WALLET(address(badLog));

        vm.deal(sender, amount + 1 ether);

        bool okRef;
        vm.prank(sender);
        try c.Put{value: amount}(unlockTime) {
            okRef = true;
        } catch {
            okRef = false;
        }

        bool okWithBadLog;
        vm.prank(sender);
        try c_bad.Put{value: amount}(unlockTime) {
            okWithBadLog = true;
        } catch {
            okWithBadLog = false;
        }

        assertTrue(!okRef);
    }
}

contract RevertingLog {
    fallback() external payable {
        revert("reverting log");
    }
    receive() external payable {
        revert("reverting log");
    }
}
